  function handleSubmit(e) {
    e.preventDefault();
    if (!onAdd) return;

    const entry = {
      style,
      rating,
      notes: notes
    };

    onAdd(entry);
    setStyle("Type of chai");
    setRating('*');
    setNotes("");
  }

  return (
    <section className="page">
      <h1>Chai Rating</h1>

